   "module": "shuliang",
   "q": "甲、乙两个单位周末分别安排60%和75%的职工下沉社区帮助困难群众，其中甲单位派出的职工比乙单位少3 人。后两单位又在剩下的职工中，分别抽调40%和75%的职工，共计24 人参加周末的业务培训。问甲单位职工人数比乙单位（ ）",
