   "module": "shuliang",
   "q": "某企业选拔170 多名优秀人才平均分配为7 组参加培训。在选拔出的人才中，党员人数比非党员多3 倍。接受培训的党员中的10%在培训结束后被随机派往甲单位等12 个基层单位进一步锻炼。已知每个基层单位至少分配1 人，问甲单位分配人数多于1 的概率在以下哪个范围内（ ）",
