   "id": "xc-2021-gk-dishi-70",
   "module": "shuliang",
   "q": "某工厂在做好防疫工作的前提下全面复工复产，复工后第1 天的产能即恢复到停工前日产能的60%，复工后每生产4 天，日产能都会比前4 天的水平提高1000 件/日。已知复工80 天后，总产量相当于停工前88 天的产量，问复工后的总产量达到100 万件是在复工后的第几天（ ）",
