   "answer": 3,
   "explain": "】交叉关系。“立体化战争”即多维空间战争，“数字化战争”是以信息为主要手 段，以信息技术为基础的战争，是信息战的一种形式，二者属于交叉关系。 A 项，民主型管理和专制型管理是两种不同的管理形式，管理形式还有放任型管理， 二者为反对关系，与题干逻辑关系不符，排除； B 项，有些观赏树木可以组成防风林，二者为或然组成关系，与题干逻辑关系不符， 排除； C 项，“有氧运动”可以瘦身，但不属于“医疗瘦身”，二者为全反关系，与题干逻辑 关系不符，排除； D 项，“绩效奖励”是根据员工的绩效考核结果给予的一次性奖励，与“物质奖励” 属于交叉关系，与题干逻辑关系相符，当选。 故正确答案为D。",
   "year": 2021,
   "exam_type": "gk-dishi",
   "exam_volume": "行测",
   "topic": "",
   "src": "真题·PDF",
   "url": ""
