   "q": "（ ）之于 口罩 相当于 竹子 之于（ ）",
   "options": [
    "耳挂；竹炭",
    "无纺布；斗笠",
    "卫生用品；竹叶",
    "医用口罩；箭竹据这段陈述，选择一个答案。注意：正确答案应与所给的陈述相符合，不需要任何附加说明即可以从陈述中直接推出。"
   ],
   "answer": 1,
   "explain": "】原材料对应关系。将选项代入题干逐一分析。 A 项，耳挂是口罩的组成部分，二者为组成关系，竹炭是由高山毛竹为原材料经千度 高温烧制而成的一种碳，所以二者构成原材料对应关系，前后逻辑关系不符，排 除； B 项，制作口罩的原材料是无纺布，两者为原材料对应关系，斗笠的原材料是竹子， 二者为原材料对应关系，前后逻辑关系相符，当选； C 项，口罩是卫生用品的一种，二者为种属关系，竹叶是竹子的组成部分，二者为组成 关系，前后逻辑关系不符，排除； D 项，医用口罩属于口罩的一种，二者为种属关系，箭竹属于竹子的一种，二者为种 属关系，但二者位置相反，前后逻辑关系不符，排除。 故正确答案为B。",
