   "module": "yanyu",
   "q": "以下这段文字最适合放在原文的哪个位置（ ）要理解在古代中国，为何“匕”作为饮食工具比筷子出现更早也更为重要，我们需要仔细考察历史上中国人通常摄入的食物种类。",
