   "answer": 1,
   "explain": "】给定文段论述了“匕”比筷子出现早也更为重要的原因，即“与中国人通常摄入 的食物种类有关”，故后文论述内容应与“历史上中国人摄入的食物种类”有关。只 有③句讲述了历史上中国人摄入的食物种类，对应B项。 故正确答案为B。",
