   "q": "某商场开展“助农销售”活动，凡购买某种农产品满300 元者可获得一个礼盒，其中装有6 种干货中的随机3 种各1 小袋，以及1 袋小米或红豆。问内容不完全相同的礼盒共有多少种可能（ ）",
