   "module": "shuliang",
   "q": "社区工作人员小张连续4 天为独居老人采买生活必需品。已知前三天共采买65 次，其中第二天采买次数比第一天多50%，第三天采买次数比前两天采买次数的和少15 次，第四天采买次数比第一天的2 倍少5 次。问这4 天中，小张为独居老人采买次数最多和最少的日子，单日采买次数相差多少次（ ）",
