   "answer": 1,
   "explain": "B 么总人数为1 + 4 = 5的倍数，总人数可平均分为7 组，说明总人数为7 的倍数，总 数既是5 的倍数又是7 的倍数且为170 多则只能是175，那么党员人数为175 × 全国服务电话：400-6353-606 第四次直播 第五次直播 第六次直播 销售额 销售额 销售额 5 = 4 140。党员人数的10%为14 人，将14 人分给12 个单位，每个都不为空，总的情况 11＝C",
