   "answer": 1,
   "explain": "】几何问题。露出水面部分的体积增加 125 现在的高与原来的高的比为5: 4，原来的高为3 米，则现在的高为 与原来的体积之比为 4 −3 = 3 4米，人工湖水深减少20%，那么原来的人工湖水深为 3 15 20% = 15 4 米= 3.75 米。 原来的高多了 故正确答案为B。",
